import { FC, useEffect, useRef, useState } from 'react';

import styled from 'styled-components';

import type OpenFin from '@openfin/core';

import { Icon } from '@openfin/ui-library';

import { getUrlParams, Router, withRouter } from '@common/utils/router';

import { useTranslation } from '@common/api/i18next';

import { getContextGroupColorForView } from '@enterprise/api/color-linking';

import Callout from '@enterprise/components/Callout/Callout';
import PopupButton from '@enterprise/components/ControlBar/BaseButton/PopupButton';
import { ColorLinkingChannelTypes } from '@enterprise/components/ControlBar/RightControlsContainer/ToolbarContainer/buttons/ColorLinkingButton/ColorLinkingButton';

interface Props {
    router: Router;
}

const ColorLinkingPopup: FC<Props> = ({ router }) => {
    const urlParams = getUrlParams(router.asPath);
    const parentName = urlParams.parentName ?? '';
    const invocationId = urlParams.invocationId ?? '';
    const [selectedView, setSelectedView] = useState<OpenFin.Identity[]>([]);
    const [contextGroups, setContextGroups] = useState([]);
    const [currentColor, setCurrentColor] = useState('');
    const channelToParent = useRef<BroadcastChannel>();
    const { t } = useTranslation();

    useEffect(() => {
        const params = getUrlParams(router.asPath);

        if (typeof params.selectedViews === 'string' && params.selectedViews !== 'undefined') {
            const routerSelectedView: OpenFin.Identity[] = JSON.parse(params.selectedViews ?? '[]');
            setSelectedView(routerSelectedView);
            updateCurrentColor(routerSelectedView);
        }
    }, [router]);

    const updateCurrentColor = async (currentViews: OpenFin.Identity[]) => {
        if (currentViews.length > 1) {
            const p = await Promise.all(currentViews.map((v) => getContextGroupColorForView(v)));
            if (p.length > 0 && p.every((c) => c?.name === p?.[0]?.name)) {
                setCurrentColor(p[0].name);
            } else {
                setCurrentColor('');
            }
        } else {
            setCurrentColor((await getContextGroupColorForView(currentViews[0] || selectedView[0]))?.name);
        }
    };

    const applyContextGroup = async (name: string, id: string) => {
        const colorName = name[0].toUpperCase() + name.substring(1);

        if (name === currentColor) {
            channelToParent.current.postMessage({
                type: ColorLinkingChannelTypes.LEAVE_GROUP,
                channelId: id,
                colorName
            });
        } else {
            channelToParent.current.postMessage({
                type: ColorLinkingChannelTypes.JOIN_GROUP,
                channelId: id,
                colorName
            });
        }

        // Blur the window so that it is hidden by logic in MenuWindow
        fin.Window.getCurrentSync().blur();
    };

    useEffect(() => {
        fin.me.interop.getContextGroups().then((groups) => setContextGroups(groups));
    }, [invocationId]);

    useEffect(() => {
        channelToParent.current = new BroadcastChannel(`color-linking-${parentName}`);

        return () => {
            channelToParent.current.close();
        };
    }, [parentName]);

    return (
        <Callout aria-label={t('aria.closeContextGroup')}>
            <PopupButton
                title={t('aria.colorLinking')}
                aria-label={t('aria.colorLinking')}
                onClick={() => {
                    channelToParent.current.postMessage({
                        type: ColorLinkingChannelTypes.SHOW_HIDE_GROUPS
                    });
                }}
            >
                <Icon icon="EyeOpenIcon" />
            </PopupButton>

            {contextGroups.map(({ id, displayMetadata: { color, name } }) => (
                <PopupButton
                    disabled={selectedView.length === 0}
                    key={id}
                    withTitleCase={false}
                    title={selectedView.length === 0 ? t('aria.applyColorLinking') : name}
                    icon=""
                    aria-label={
                        selectedView.length === 0
                            ? t('aria.applyColorLinking')
                            : name === currentColor
                            ? selectedView.length > 1
                                ? t('aria.assignColorLinkingCurrentView', { name })
                                : t('aria.assignColorLinkingCurrentViews', { name })
                            : selectedView.length > 1
                            ? t('aria.setColorLinkingActiveView')
                            : t('aria.setColorLinkingActiveViews')
                    }
                    onClick={() => applyContextGroup(name, id)}
                >
                    <ColorIcon style={{ backgroundColor: color }} />
                </PopupButton>
            ))}
        </Callout>
    );
};

export default withRouter(ColorLinkingPopup);

const ColorIcon = styled.div`
    border-radius: ${({ theme }) => theme.radius.round};
    height: ${({ theme }) => theme.px.base};
    width: ${({ theme }) => theme.px.base};
    margin: 10px;
`;
