import { useEffect } from 'react';

import { useTranslation } from '@common/api/i18next';

import { Locale } from '@client-platform/shapes';

export const useLanguageChange = (onLanguageChange: (language: Locale) => void) => {
    const { i18n } = useTranslation();

    useEffect(() => {
        const eventHandler = () => {
            onLanguageChange(i18n.language as Locale);
        };
        i18n.on('languageChanged', eventHandler);

        return () => {
            i18n.off('languageChanged', eventHandler);
        };
    }, [i18n, onLanguageChange]);
};
