import React, { useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { Menu, UserMenuParams } from '@common/utils/menu';
import { RightMenuConfig } from '@common/utils/menu-config';
import { showModalWin } from '@common/utils/popup-window';

import { closeActiveMenu, openMenu, selectActiveMenu } from '@enterprise/slices/menu';

import ExtendedButton from '../BaseButton/ExtendedButton';

interface Props<M extends Menu> {
    'type': M;
    'config': RightMenuConfig;
    'params': UserMenuParams[M];
    'disabled'?: boolean;
    'tooltip'?: string;
    'data-testid'?: string;
}

/**
 * Generic element for displaying a button that opens a popup menu
 */
const MenuButton = <M extends Menu>({
    params,
    type,
    config,
    disabled,
    children,
    tooltip,
    'data-testid': dataTestId
}: React.PropsWithChildren<Props<M>>): React.ReactElement => {
    const dispatch = useDispatch();
    const buttonRef = useRef<HTMLButtonElement | null>(null);
    const activeMenu = useSelector(selectActiveMenu);
    const isActive = useRef<boolean>(false);
    isActive.current = activeMenu.type === type && !!activeMenu.type;

    const { windowOptions, windowOffset } = config;

    const onClickHandler = () => {
        if (!buttonRef.current) {
            throw new Error('Button ref is undefined');
        }

        const { bottom, left } = buttonRef.current.getBoundingClientRect();
        const offsetX = (windowOffset?.x || 0) + buttonRef.current.offsetWidth / 2;
        (async () => {
            const windowOpts = {
                x: left + offsetX - windowOptions.defaultWidth / 2,
                y: bottom,
                ...windowOptions
            };

            // Menu needs update state on blur, setup here prior to showing window so there is no chance of a timing issue
            const win = fin.Window.wrapSync({ uuid: fin.me.uuid, name: windowOpts.name });
            let hasBeenFocused = false;
            const blurredListenerPromise = win.once('blurred', () => {
                if (hasBeenFocused) {
                    dispatch(closeActiveMenu());
                }
            });
            const focusedListenerPromise = win.once('focused', () => {
                // Only change the window button state once the menu has been shown & focused
                dispatch(openMenu(type, params));
                // Ensure that the window has been focused once so there is no timing issue
                hasBeenFocused = true;
            });
            await Promise.all([blurredListenerPromise, focusedListenerPromise]);

            await showModalWin(params, windowOpts);
        })();
    };
    return (
        <ExtendedButton
            title={tooltip}
            disabled={disabled ?? false}
            onClick={onClickHandler}
            active={isActive.current}
            ref={buttonRef}
            data-testid={dataTestId}
        >
            {children}
        </ExtendedButton>
    );
};

export default MenuButton;
